<?php require_once __DIR__.'/../includes/bootstrap.php';require_login();$q=db()->query("SELECT b.*,COUNT(bc.id) copies,SUM(bc.status='Available') available FROM books b LEFT JOIN book_copies bc ON bc.book_id=b.id GROUP BY b.id ORDER BY b.title");page_top('Book Catalog');?><div class='card p-3 table-responsive'><table class='table'><tr><th>ISBN</th><th>Title</th><th>Author</th><th>Category</th><th>Copies</th><th>Available</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['isbn'])?></td><td><?=e($r['title'])?></td><td><?=e($r['author'])?></td><td><?=e($r['category'])?></td><td><?=e($r['copies'])?></td><td><?=e($r['available'])?></td></tr><?php endforeach;?></table></div><?php page_bottom();
